import{_ as e,c as a,o,ae as n}from"./chunks/framework.Bi6zybwU.js";const b=JSON.parse('{"title":"Create Your First Table","description":"Create Your First Table","frontmatter":{"title":"Create Your First Table","description":"Create Your First Table"},"headers":[],"relativePath":"guide/creating-tables/create-your-first-table.md","filePath":"guide/creating-tables/create-your-first-table.md"}'),i={name:"guide/creating-tables/create-your-first-table.md"};function l(r,t,s,c,u,d){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="create-your-first-table" tabindex="-1">Create Your First Table <a class="header-anchor" href="#create-your-first-table" aria-label="Permalink to &quot;Create Your First Table&quot;">​</a></h1><p>Creating a table with <strong>Ninja</strong> <strong>Tables</strong> is simple and fast! Install and activate Ninja Tables on your dashboard and try all the magic tricks this plugin comes with. Let&#39;s look at how to create a table.</p><h2 id="add-table" tabindex="-1">Add Table <a class="header-anchor" href="#add-table" aria-label="Permalink to &quot;Add Table&quot;">​</a></h2><ul><li>First, go to the <strong>WordPress Dashboard</strong>. Then navigate to the <strong>Ninja Tables</strong> <strong>Plugin</strong> from the sidebar.</li><li>Now, Click the blue &quot;<strong>Create New Table</strong>&quot; button on your screen&#39;s top right.</li><li>After clicking the button, a popup will appear with a menu of multiple table creation options. <img src="https://ninjatables.com/wp-content/uploads/2025/05/Table-creation-option-UI-1024x536.webp" alt="New UI Table creation option"></li><li>Ninja Tables offers 8 dynamic table creation options here, including WooCommerce product tables and Google SHeet auto-sync. You can pick any option to create a new table. We&#39;re picking the &quot;Default&quot; or manual table creation.</li><li>You can see some text boxes on the right side under &quot;Manually Create a Table&quot;- Table Title &amp; Description.</li><li>Give your table a name first (it&#39;s required), description (optional), and then, hit the <strong>Add</strong> button to add the table.</li><li>Clicking on the <strong>Add</strong> button will send you to the <strong>Table Rows</strong> tab. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-UI-add-table-column-1024x344.webp" alt="New UI add table column"></li></ul><h2 id="table-rows" tabindex="-1">Table Rows <a class="header-anchor" href="#table-rows" aria-label="Permalink to &quot;Table Rows&quot;">​</a></h2><ul><li><p>Initially, in the <strong>Table Rows</strong> tab, you will find only the &quot;<strong>+ Add</strong> <strong>Column</strong>&quot; button to create columns. And several other tabs to configure the table. We&#39;ll get to that later.</p></li><li><p>After clicking the button, a popup will appear with Column Name, Column Key (Column key will automatically generate based on your given column name), Data Type, Responsive Breakpoint for the &quot;Basic Settings,&quot; and some more configuration tabs above. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-UI-table-column-1024x461.webp" alt="New UI table column"></p></li><li><p>Add the first column primary properties from here - column name and data type. Hit the blue button below to &quot;<strong>Add Column</strong>.&quot;</p></li><li><p>After this, you will get two buttons in the top right corner of a new window.</p></li></ul><p>&quot;<strong>Add Data</strong>&quot; is for data input into the column and &quot;<strong>+ Add Column</strong>&quot; is for creating new columns. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-add-data-add-column-1024x344.webp" alt="New Ui add data add column"></p><ul><li>Here you also have Bulk Actions, Compact View, and Sort Manually options. You can use the <strong>Search Field</strong> to find the rows you&#39;re looking for (if you already have table entries).</li><li>You may quickly drag and drop table rows and arrange them as needed by enabling the <strong>Sort Manually</strong> option.</li></ul><h2 id="table-configuration-tab" tabindex="-1">Table Configuration Tab <a class="header-anchor" href="#table-configuration-tab" aria-label="Permalink to &quot;Table Configuration Tab&quot;">​</a></h2><p><img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-table-configuration-tab-1024x713.webp" alt="New Ui table configuration tab"></p><ul><li>To configure each column, you need to click on the pencil icon to get four different options- <strong>Basic Settings</strong>, <strong>Advanced Settings</strong>, <strong>Conditional Formatting</strong>, <strong>Transform Values,</strong> etc. ***After configuring each tab, you must hit &quot;<strong>Update</strong>&quot; or else no changes will be saved.</li></ul><h3 id="basic-settings" tabindex="-1">Basic Settings <a class="header-anchor" href="#basic-settings" aria-label="Permalink to &quot;Basic Settings&quot;">​</a></h3><p>Using Basic Settings, you can do basic configuration, including responsive breakpoints of your table configuration. Or change the data type of the column. You can change Column Name but Column Key will only change responding to the name. It may take a refresh.</p><h3 id="advanced-settings" tabindex="-1">Advanced Settings <a class="header-anchor" href="#advanced-settings" aria-label="Permalink to &quot;Advanced Settings&quot;">​</a></h3><p>In Advanced Settings, you can have multiple options for configuring your columns. Control column width, header and row content text alignment, enable or disable HTML header content or column filter/sort. You can also color the column background and text. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-column-advanced-settings-1024x651.webp" alt="New Ui column advanced settings"></p><h3 id="conditional-formatting" tabindex="-1">Conditional Formatting <a class="header-anchor" href="#conditional-formatting" aria-label="Permalink to &quot;Conditional Formatting&quot;">​</a></h3><p>Conditional Formatting will allow you to add a condition for formatting your columns in very different ways. From here, you can change cell color, cell content, set CSS class, and more. Insert as many conditions you want by clicking &quot;+&quot;, just remember to hit &quot;<strong>Update</strong>.&quot; <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-conditional-formatting-tab-1024x712.webp" alt="New Ui conditional formatting tab"></p><h3 id="transform-value" tabindex="-1">Transform Value <a class="header-anchor" href="#transform-value" aria-label="Permalink to &quot;Transform Value&quot;">​</a></h3><p>Using Transform Value, you can change the plain text of a column to clickable hyperlinks. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-transform-value-tab-1024x707.webp" alt="New Ui transform value tab"></p><h2 id="table-design-tab" tabindex="-1">Table Design Tab <a class="header-anchor" href="#table-design-tab" aria-label="Permalink to &quot;Table Design Tab&quot;">​</a></h2><p>In this section, you will find three design options for configuring your tables.</p><ul><li><strong>Styling</strong></li><li><strong>Table</strong> <strong>Colors</strong></li><li><strong>Other</strong><img src="https://ninjatables.com/wp-content/uploads/2025/05/New-UI-table-design-tabs-1024x649.webp" alt="New UI table design tabs"> This is where you can change the whole look of your table.</li></ul><h3 id="styling" tabindex="-1">Styling <a class="header-anchor" href="#styling" aria-label="Permalink to &quot;Styling&quot;">​</a></h3><p>On the right sidebar, you will notice the first tab, **Styling. **This tab itself has three separate styling options.</p><ul><li><strong>Styles</strong>: The first one is the Styling Library, which manages the library you have to work with. Three different libraries are available in this segment: <strong>Semantic UI</strong>, <strong>Bootstrap 4</strong> &amp; <strong>Bootstrap 3</strong>. Each of these libraries has various components once you select one of them.You can choose table hover, border, stripes etc.</li><li><strong>Features</strong>: The second one is the** <strong>features option which offers several functions like table title show, make table searchable</strong>,** and many more. Check these options according to your styling needs.</li><li><strong>Table Configuration</strong>: Last but not least, you can show your rows as a list item with a stackable table. You can target by device width and control stacked appearance. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-table-ui-stackable-table-703x1024.webp" alt="New table ui stackable table"></li></ul><h3 id="table-colors" tabindex="-1">Table Colors <a class="header-anchor" href="#table-colors" aria-label="Permalink to &quot;Table Colors&quot;">​</a></h3><p>You can style your table in 13 different pre-defined color schemes. Feel free to check all those color schemes. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-predefined-color-scheme-1024x437.webp" alt="New Ui predefined color scheme"> Besides these, you have a &quot;Custom Scheme&quot; with unlimited color choices. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-custom-color-scheme-1024x635.webp" alt="New Ui custom color scheme"> ***Please remember to hit the &quot;<strong>Save</strong>&quot; button above to keep your beautiful designs!</p><h3 id="other" tabindex="-1">Other <a class="header-anchor" href="#other" aria-label="Permalink to &quot;Other&quot;">​</a></h3><p><strong>Pagination -</strong> Under the <strong>Other</strong> option, you will find the pagination section. In this section, you can select how many items you want to show per page. You can also disable pagination here. Click on the <strong>Save</strong> button after finishing up your table configuration.</p><h2 id="add-duplicate-delete-rows" tabindex="-1">Add, Duplicate, Delete Rows <a class="header-anchor" href="#add-duplicate-delete-rows" aria-label="Permalink to &quot;Add, Duplicate, Delete Rows&quot;">​</a></h2><ul><li>In the Table Rows tab, you can also manage your data by deleting or updating.</li><li>You will find icons for editing, duplicating, add new row and row delete options in the &quot;<strong>Actions</strong>&quot; column of the table backend. This column will not be visible in the table frontend. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-add-delete-or-duplicate-row-1024x449.webp" alt="New Ui add delete or duplicate row"></li></ul><h2 id="add-table-to-frontend" tabindex="-1">Add table to frontend <a class="header-anchor" href="#add-table-to-frontend" aria-label="Permalink to &quot;Add table to frontend&quot;">​</a></h2><p>To incorporate a table into your website, navigate to Ninja Tables where you&#39;ll find all your tables listed. Select the specific table you want to show, then click on its shortcode to copy it. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-embed-shortcode-1024x435.webp" alt="New Ui embed shortcode"> This shortcode is auto-generated. Paste the Shortcode on your desired page or post anywhere you want. You can also easily add your table using the <strong>Ninja Tables block</strong>. Simply go to the page or post where you&#39;d like to embed your table. Look for the <strong>Ninja Tables Block</strong> and insert it. You&#39;ll find a search field where you can look up the specific table you want to display on your frontend. Now click on the table name to insert it. Change table color from post/page backend. But remember, the design changes made here will apply to this specific table in the Ninja Tables&#39; &quot;All Tables&quot; dashboard. The block won&#39;t create a new table for you to design. Use Bulk Action if you need to delete more than one entry. You can also duplicate each table using the icon in the table dashboard. Let&#39;s visually look at the video demonstration of the basic table setup using the Ninja Tables plugin. <a href="https://youtu.be/GXqaXMVsnl8?si=QaKnjDwnh6yvo3ar" target="_blank" rel="noreferrer">https://youtu.be/GXqaXMVsnl8?si=QaKnjDwnh6yvo3ar</a></p>',33)])])}const g=e(i,[["render",l]]);export{b as __pageData,g as default};
